1	import { writable, derived } from 'svelte/store';
2	import type { Note, Todo, Settings, SyncResult, View, Project } from './types';
3	
4	function localStore<T>(key: string, initial: T) {
5	  const stored = typeof localStorage !== 'undefined' ? localStorage.getItem(key) : null;
6	  const store = writable<T>(stored !== null ? JSON.parse(stored) : initial);
7	  store.subscribe((v) => {
8	    if (typeof localStorage !== 'undefined') localStorage.setItem(key, JSON.stringify(v));
9	  });
10	  return store;
11	}
12	
13	export const notes = writable<Note[]>([]);
14	export const todos = writable<Todo[]>([]);
15	export const diskFolders = writable<string[]>([]);
16	export const settings = writable<Settings>({
17	  repo_path: '',
18	  repo_url: '',
19	  git_username: '',
20	  git_email: '',
21	  git_token: '',
22	  auto_sync: true,
23	  sync_interval_seconds: 30,
24	});
25	
26	// User-defined project shortcuts (synced via projects.json). Loaded from the backend.
27	export const projects = writable<Project[]>([]);
28	// Which project filter is currently applied — drives the nav highlight. Not
29	// persisted: the view always returns to Home on startup, so a remembered project
30	// id would highlight a project while Home is actually shown.
31	export const activeProjectId = writable<string | null>(null);
32	
33	// The currently-applied project (or null). Its tags act as a hard prefilter on the
34	// Tasks view: only tasks carrying at least one of these tags are shown, the tags are
35	// hidden from the page filter/group chips, and new tasks inherit them automatically.
36	export const activeProject = derived(
37	  [projects, activeProjectId],
38	  ([$projects, $id]) => ($id ? $projects.find((p) => p.id === $id) ?? null : null)
39	);
40	export const activeProjectTags = derived(activeProject, ($p) => $p?.tags ?? []);
41	
42	// Set to a todo id to ask the Tasks view to open that task in focus mode. The
43	// Tasks view consumes and clears it. Lets the sidebar jump back to the running task.
44	export const focusRequest = writable<string | null>(null);
45	
46	// Bumped every time a project is applied from the sidebar. The Tasks view watches
47	// it to leave focus mode and show the full list — even when the same project that
48	// is already active is re-clicked (which wouldn't change activeProjectId).
49	export const projectApplyTick = writable(0);
50	
51	export const activeView = writable<View>('home');
52	export const theme = writable<'system' | 'light' | 'dark' | 'midnight' | 'forest'>('system');
53	export const activeTimers = writable<Map<string, number>>(new Map());
54	export const selectedNoteId = writable<string | null>(null);
55	export const showSettings = writable(false);
56	
57	export interface SyncState {
58	  syncing: boolean;
59	  lastResult: SyncResult | null;
60	  lastSync: string | null;
61	}
62	export const syncState = writable<SyncState>({
63	  syncing: false,
64	  lastResult: null,
65	  lastSync: null,
66	});
67	
68	export const taskFilterStatus = localStore<'all' | 'pending' | 'done'>('todoto-filter-status', 'all');
69	export const taskFilterPriority = localStore<'' | 'none' | 'high' | 'medium' | 'low'>('todoto-filter-priority', '');
70	export const taskFilterTag = localStore<string>('todoto-filter-tag', '');
71	export const taskFilterDuePeriod = localStore<'' | 'overdue' | 'today' | 'week' | 'month'>('todoto-filter-due', '');
72	export const taskFilterGroupByTags = localStore<string[]>('todoto-filter-group-tags', []);
73	export const taskFilterSearch = localStore<string>('todoto-filter-search', '');
74	export const taskFilterShowOther = localStore<boolean>('todoto-filter-show-other', false);
75	export const taskFilterHideUngrouped = localStore<boolean>('todoto-filter-hide-ungrouped', false);
76	// Whether tags/labels are shown on todo rows in their unselected/inactive state.
77	// A clicked or selected task always shows its tags regardless of this setting.
78	export const taskShowTags = localStore<boolean>('todoto-show-tags', true);
79	// Hairline dividers between todo rows. Off gives a cleaner, borderless list.
80	export const taskShowDividers = localStore<boolean>('todoto-show-dividers', true);
81	
82	// Today's hand-picked workload: a date + the ids of todos selected for that day.
83	// Todos are referenced by id only — they don't know they're picked. A stored date
84	// other than today means the selection is stale and treated as empty.
85	export const todaySelection = localStore<{ date: string; ids: string[] }>('todoto-today', { date: '', ids: [] });
86	
87	// When true, the Tasks view is filtered to today's hand-picked workload. A view
88	// filter (not a separate page) so the task cards/behaviour are identical.
89	export const taskFilterToday = writable(false);
90	
91	/** Local calendar day as YYYY-MM-DD — the key that scopes the daily selection. */
92	export function todayKey(): string {
93	  const d = new Date();
94	  return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`;
95	}
96	
97	// Id of the todo currently being dragged (null when not dragging). Shared so the
98	// sidebar "Today" nav item can act as a drop target for pinning to today.
99	export const draggingTodoId = writable<string | null>(null);
100	// True while a drag is hovering the sidebar "Today" item (drives its highlight,
101	// since :hover isn't reliable during a mouse-button-held drag in some webviews).
102	export const dragOverToday = writable(false);
103	
104	/** Add a todo id to today's selection (scoped to the current day). */
105	export function pinTodoToToday(id: string) {
106	  const key = todayKey();
107	  todaySelection.update((sel) => {
108	    const ids = sel.date === key ? [...sel.ids] : [];
109	    if (!ids.includes(id)) ids.push(id);
110	    return { date: key, ids };
111	  });
112	}
113	
114	export const pendingTodos = derived(todos, ($todos) => $todos.filter((t) => !t.done));
115	export const doneTodos = derived(todos, ($todos) => $todos.filter((t) => t.done));
116	export const pinnedNotes = derived(notes, ($notes) => $notes.filter((n) => n.pinned));
117	export const recentNotes = derived(notes, ($notes) =>
118	  [...$notes].sort((a, b) => b.updated_at.localeCompare(a.updated_at)).slice(0, 5)
119	);
